// Source list - THE single place to add/remove/rename a feed.
const SOURCES = [
  {
    "name": "dev.to",
    "tag": "devto",
    "url": "https://dev.to/feed"
  },
  {
    "name": "Hacker News",
    "tag": "hn",
    "url": "https://hnrss.org/frontpage"
  },
  {
    "name": "Journal du Hacker",
    "tag": "jdh",
    "url": "https://www.journalduhacker.net/rss"
  },
  {
    "name": "Korben",
    "tag": "kbn",
    "url": "https://korben.info/feedfull"
  },
  {
    "name": "Next",
    "tag": "nxt",
    "url": "https://next.ink/feed/free"
  }
];
return SOURCES.map((s) => ({ json: s }));

// Re-attach the current source's identity to every fetched item.
// The RSS Read node drops its input fields, so the loop context is the only
// place that still knows which source this batch came from.
const src = $('Loop sources').first().json;
return $input.all().map((i) => ({ json: { ...i.json, source: src.tag, sourceName: src.name } }));

// Normalize RSS items to {title, url, source, publishedAt, excerpt}
// Rules (spec 02): strip HTML, drop missing URL, drop older than 48h,
// sort by publishedAt desc, cap at 60 items.
const cutoff = Date.now() - 48 * 3600 * 1000;
const strip = (s) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#39;|&apos;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')
  .trim();

const out = [];
for (const { json } of $input.all()) {
  const url = json.link;
  // Only http(s) links: a feed could carry a javascript: URL, which would
  // execute on click once rendered as an href (the viewer guards too).
  if (!url || !/^https?:\/\//i.test(url)) continue;
  const ts = Date.parse(json.isoDate || json.pubDate || '');
  if (!ts || ts < cutoff) continue;
  out.push({
    json: {
      title: strip(json.title),
      url,
      source: json.source,
      sourceName: json.sourceName,
      publishedAt: new Date(ts).toISOString(),
      excerpt: strip(json.contentSnippet || json.content).slice(0, 300),
    },
  });
}

out.sort((a, b) => b.json.publishedAt.localeCompare(a.json.publishedAt));
return out.slice(0, 60).map((it, i) => ({ json: { id: i, ...it.json } }));

// Parse the LLM's id selection and filter the deduped candidate list.
// Identity fields (url/title) never pass through the LLM: it selects by id only,
// so a hallucinated or mangled URL is impossible by construction (spec 03).
const first = $input.first().json;
const raw = String(first.text ?? first.output ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let ids;
try {
  ids = JSON.parse(cleaned);
} catch (e) {
  throw new Error('LLM returned non-JSON output: ' + raw.slice(0, 200));
}
if (!Array.isArray(ids) || !ids.every((n) => Number.isInteger(n))) {
  throw new Error('LLM output is not a JSON array of integer ids: ' + cleaned.slice(0, 200));
}

// Resolved against Drop published, not Normalize: an id excluded as already
// published is therefore rejected below rather than silently re-admitted.
const byId = new Map($('Drop published').first().json.data.map((it) => [it.id, it]));
const seen = new Set();
const selected = [];
for (const id of ids) {
  if (seen.has(id)) continue;
  seen.add(id);
  const item = byId.get(id);
  if (item === undefined) throw new Error('LLM returned an id absent from the input list: ' + id);
  selected.push(item);
  if (selected.length >= 10) break;
}
if (selected.length === 0) throw new Error('LLM selected no valid items');
// Emit ONE bundled item ({data: [...]}, same shape as an Aggregate node) so the
// next LLM chain runs once for the batch - replaces the former Bundle selected node.
return [{ json: { data: selected } }];

// Enforce spec 04. Identity fields (title/url/source) NEVER pass through the
// LLM - they are rebuilt from the original items by id, so URLs cannot be
// altered by construction. The LLM only contributes category/tags/tldr.
const CATEGORIES = new Set(['ai', 'dev', 'devops', 'security', 'other']);
const out = $input.first().json.output;
const records = Array.isArray(out) ? out : out?.items;
if (!Array.isArray(records)) throw new Error('Parser output has no items array');

const selected = $('Filter selected').first().json.data;
if (records.length !== selected.length) {
  throw new Error(`Expected ${selected.length} records, got ${records.length}`);
}
const byId = new Map(records.map((r) => [r.id, r]));
const result = [];
for (const sel of selected) {
  const rec = byId.get(sel.id);
  if (!rec) throw new Error('No record for item id ' + sel.id);
  if (!CATEGORIES.has(rec.category)) throw new Error(`Invalid category "${rec.category}" for id ${sel.id}`);
  if (!Array.isArray(rec.tags) || rec.tags.length < 1 || rec.tags.length > 4) {
    throw new Error('tags must have 1-4 entries for id ' + sel.id);
  }
  if (typeof rec.tldr !== 'string' || rec.tldr.trim().length === 0) {
    throw new Error('Empty tldr for id ' + sel.id);
  }
  const { id, ...original } = sel;
  result.push({ json: { ...original, category: rec.category, tags: rec.tags, tldr: rec.tldr.trim() } });
}
return result;

// Assemble the day's digest as a publishable JSON payload.
// The site (docs/digest.html) renders it client-side - the workflow ships DATA,
// never markup. Layout/styling live in the viewer page, committed once.
const records = $('Validate extraction').all().map((i) => i.json);
if (records.length === 0) throw new Error('No records to publish');
const intro = String($input.first().json.text ?? '').trim();
if (!intro) throw new Error('Empty intro from LLM');

const now = new Date();
const date = now.toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' }); // YYYY-MM-DD
return [{
  json: {
    date,
    generatedAt: now.toISOString(),
    intro,
    count: records.length,
    items: records.map(({ title, url, source, sourceName, publishedAt, category, tags, tldr }) =>
      ({ title, url, source, sourceName, publishedAt, category, tags, tldr })),
  },
}];

// Build the GitHub contents-API bodies + the Discord message.
// PUT to the contents API creates OR updates: sha present = update, absent = create.
// The index (docs/digests.json) is a pure date array - add today only if absent.
const payload = $('Build payload').first().json;
const idx = $('Get index').first().json;
const dates = JSON.parse(Buffer.from(idx.content, 'base64').toString('utf8'));
if (!Array.isArray(dates)) throw new Error('digests.json on remote is not a JSON array');

const existing = $input.first().json;
const payloadSha = existing.error ? null : existing.sha;

const indexChanged = !dates.includes(payload.date);
const newDates = indexChanged ? [payload.date, ...dates].sort().reverse() : dates;

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const payloadBody = {
  message: `digest: ${payload.date}`,
  content: b64(JSON.stringify(payload, null, 2) + '\n'),
};
if (payloadSha) payloadBody.sha = payloadSha;

const indexBody = indexChanged ? {
  message: `digest index: ${payload.date}`,
  content: b64(JSON.stringify(newDates, null, 2) + '\n'),
  sha: idx.sha,
} : null;

const top = payload.items.slice(0, 3).map((i) => `\u2022 ${i.title}`);
const discordContent = [
  `\ud83d\udcda Veille tech ${payload.date} \u2014 ${payload.count} liens`,
  ...top,
  `\u2192 https://polluux.github.io/n8n-watch-dummy/digest.html?d=${payload.date}`,
].join('\n');

return [{ json: { date: payload.date, indexChanged, payloadBody, indexBody, discordContent } }];

// The cross-day exclusion window: the LOOKBACK_DAYS days before today (Europe/Paris),
// one item per date. "Get recent digests" then fetches each day's published payload;
// a 404 simply means no digest that day (cold start, or a day without a run).
const LOOKBACK_DAYS = 7;

const today = new Date().toLocaleDateString('fr-CA', { timeZone: 'Europe/Paris' }); // YYYY-MM-DD
const [y, m, d] = today.split('-').map(Number);

const out = [];
for (let back = 1; back <= LOOKBACK_DAYS; back++) {
  // Calendar arithmetic at UTC noon: month/year rollover handled, no DST edge cases
  // (subtracting fixed 24h spans would skip or repeat a day across a DST change).
  const day = new Date(Date.UTC(y, m - 1, d - back, 12));
  out.push({ json: { date: day.toISOString().slice(0, 10) } });
}
return out;

// Cross-day deduplication. Candidates already published in the last 7 days are dropped
// before the LLM ever sees them, so re-publishing a link is impossible by construction
// (same principle as identity fields never round-tripping through a model).
// The already-covered headlines travel on to the Select links prompt, which lets the
// model also skip a different source's take on a story it already ran.
const candidates = $('Normalize').all().map((i) => i.json);
if (candidates.length === 0) throw new Error('No normalized items to select from');

// Feeds re-emit the same article with varying tracking params; compare on a canonical
// form so ?utm_source=... variants of one link still match yesterday's entry.
const TRACKING = /^(utm_[a-z_]*|fbclid|gclid|mc_cid|mc_eid|ref|ref_src)$/i;
const canon = (raw) => {
  try {
    const u = new URL(String(raw));
    u.hash = '';
    u.hostname = u.hostname.toLowerCase().replace(/^www\./, '');
    for (const k of [...u.searchParams.keys()]) if (TRACKING.test(k)) u.searchParams.delete(k);
    u.pathname = u.pathname.replace(/\/+$/, '');
    return u.protocol + '//' + u.hostname + u.pathname + u.search;
  } catch (e) {
    return String(raw).trim().toLowerCase();
  }
};

const publishedUrls = new Set();
const covered = [];
let daysRead = 0;

for (const { json } of $input.all()) {
  if (json.error !== undefined) {
    // A missing day is expected. Anything else - auth, rate limit, network - must not
    // silently degrade into "nothing to exclude" and quietly reprint yesterday's links.
    const detail = typeof json.error === 'string' ? json.error : JSON.stringify(json.error);
    // A GitHub 404 surfaces as NodeApiError{description:'Not Found'} whose message reads
    // "could not be found" and carries no status code - match both phrasings.
    if (/\b404\b|not\s+(?:be\s+)?found/i.test(detail)) continue;
    throw new Error('Could not read a recent digest: ' + detail.slice(0, 200));
  }
  // Fetched with the raw media type, so the payload arrives already parsed.
  const items = json.items;
  if (!Array.isArray(items)) {
    throw new Error('Recent digest has no items array: ' + JSON.stringify(json).slice(0, 200));
  }
  daysRead++;
  for (const it of items) {
    if (!it || !it.url) continue;
    publishedUrls.add(canon(it.url));
    if (it.title) covered.push(it.title);
  }
}

const data = candidates.filter((c) => !publishedUrls.has(canon(c.url)));
if (data.length === 0) {
  throw new Error(
    `All ${candidates.length} candidate(s) were already published in the last ${daysRead} digest(s)`,
  );
}
console.log(
  `dedup: ${daysRead} recent digest(s), ${publishedUrls.size} published url(s), ` +
    `${candidates.length} candidates -> ${data.length} after exclusion`,
);

// One bundled item ({data: [...]}, the shape an Aggregate node produces) so the LLM
// chain downstream runs once for the whole batch.
return [{ json: { data, covered } }];
